);
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS contact_email TEXT;                              -- Primary contact email, shown in the Contact section on Home and Work.
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS contact_phone TEXT;                              -- Contact phone number, as it appears on the resume header.
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS site_domain TEXT;                                -- Canonical site domain.
ALTER TABLE site_settings ADD COLUMN IF NOT EXISTS portfolio_company_count TEXT;                    -- Standardized portfolio count string, per Content Strategy Section 6 ('100+' everywhere, never 107 or 111).
