ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS company TEXT;                                      -- Employer or entity name.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS job_title TEXT;                                    -- Title held. Null on the single synthetic 'earlier roles' compressed row.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS start_date DATE;                                   -- Start, YYYY-MM.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS end_date DATE;                                     -- End, YYYY-MM. Null if current.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS is_current BOOLEAN;                                -- True if this role is ongoing.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS display_group_key TEXT;                            -- Rows sharing this key render as one entry in Variant A (which uses the coarser grouping). Null where no grouping applies.
