ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS summary_text_variant_b TEXT;                       -- Bullet-point summary as it appears in Resume Variant B, bullets joined with \n.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS compressed_line TEXT;                              -- One-line compressed text, used only on the synthetic 'earlier roles' row for Variant A's single-line pre-2019 summary.
