ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS include_in_variant_b BOOLEAN;                      -- Whether this row is shown on Resume Variant B.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS is_pre2019 BOOLEAN;                                -- True for roles before 2019, compressed in Variant A per Content Strategy Section 7.
ALTER TABLE job_entries ADD COLUMN IF NOT EXISTS sort_order INTEGER;                                -- Reverse chronological display order.
